/**
 * Shared UX helpers for onboarding, data quality, and sustainability storytelling.
 */

import {
  IMPLEMENTED_RECOMMENDATIONS_STORAGE_KEY,
  clamp,
  computeEnvironmentalEquivalents as computeEnvironmentalEquivalentsCore,
  computeDataQualityScore as computeDataQualityScoreCore,
  computeCustomerHealthScore as computeCustomerHealthScoreCore,
} from '../shared/sustainabilityUxCore.js';

export type DataConfidenceLevel = 'high' | 'medium' | 'low';

export interface DataQualityInput {
  hasProfile: boolean;
  hasAssessment: boolean;
  carbonEmissionsKg: number;
  transactionCount?: number;
  documentCount?: number;
  hasScopeBreakdown?: boolean;
  /** From inventoryMetadata.completenessScore (0–100) when available. */
  inventoryCompletenessScore?: number;
  /** Share of transactions with activity-based quantification (0–100). */
  activitySharePct?: number;
}

export interface DataQualityResult {
  score: number;
  level: DataConfidenceLevel;
  label: string;
  hints: string[];
}

export interface OnboardingStep {
  id: string;
  label: string;
  description: string;
  path: string;
  complete: boolean;
  /** Rough time estimate shown to MSME users. */
  estimatedMinutes?: number;
}

export interface OnboardingProgress {
  steps: OnboardingStep[];
  completedCount: number;
  totalCount: number;
  percent: number;
  allComplete: boolean;
}

export interface NextBestAction {
  title: string;
  description: string;
  path: string;
  impactLabel?: string;
  effortLabel?: string;
  ctaLabel: string;
}

export interface EnvironmentalEquivalents {
  treesEquivalent: number;
  carsOffRoadDays: number;
  kwhEquivalent: number;
}

export {
  IMPLEMENTED_RECOMMENDATIONS_STORAGE_KEY,
  CARBON_WIZARD_DRAFT_STORAGE_KEY,
} from '../shared/sustainabilityUxCore.js';

export function computeDataQualityScore(input: DataQualityInput): DataQualityResult {
  return computeDataQualityScoreCore({ ...input, platform: 'web' }) as DataQualityResult;
}

export function deriveOnboardingSteps(input: {
  hasProfile?: boolean;
  /** @deprecated Ops mapping is advanced — ignored for the linear MSME checklist. */
  hasWorkflow?: boolean;
  hasDocuments: boolean;
  hasAssessment: boolean;
  /** True after the user picks a report goal on /reporting. */
  hasReportGoal?: boolean;
}): OnboardingProgress {
  const steps: OnboardingStep[] = [];

  if (typeof input.hasProfile === 'boolean') {
    steps.push({
      id: 'profile',
      label: 'Complete company profile',
      description: 'Confirm GST, Udyam, industry, and contact details — required for verification and buyer audits.',
      path: '/msme-profile',
      complete: input.hasProfile,
      estimatedMinutes: 5,
    });
  }

  steps.push(
    {
      id: 'documents',
      label: 'Upload your bills',
      description: 'Electricity, fuel, or purchase invoices — we read them automatically.',
      path: '/document-upload',
      complete: input.hasDocuments,
      estimatedMinutes: 3,
    },
    {
      id: 'assessment',
      label: 'Calculate your footprint',
      description: 'Answer a few questions about your operations to see where emissions come from.',
      path: '/carbon-footprint?section=start-assessment',
      complete: input.hasAssessment,
      estimatedMinutes: 15,
    },
    {
      id: 'report',
      label: 'Pick your report goal',
      description: 'Choose buyer, bank, or export — we open the matching disclosure pack.',
      path: '/reporting',
      complete: Boolean(input.hasReportGoal),
      estimatedMinutes: 5,
    },
  );

  const completedCount = steps.filter((s) => s.complete).length;
  const totalCount = steps.length;

  return {
    steps,
    completedCount,
    totalCount,
    percent: totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0,
    allComplete: completedCount === totalCount,
  };
}

export function deriveNextBestAction(input: {
  hasProfile: boolean;
  hasDocuments: boolean;
  hasAssessment: boolean;
  /** @deprecated Ops mapping is advanced — ignored for linear MSME next actions. */
  hasWorkflow?: boolean;
  hasReportGoal?: boolean;
  carbonScore: number;
  topRecommendationTitle?: string;
  topRecommendationKg?: number;
}): NextBestAction {
  if (!input.hasProfile) {
    return {
      title: 'Start with your company details',
      description: 'Tell us your sector and location — we use this to suggest realistic benchmarks and compliance paths.',
      path: '/msme-profile',
      effortLabel: '~5 min',
      ctaLabel: 'Add company details',
    };
  }

  if (!input.hasDocuments) {
    return {
      title: 'Upload an electricity or fuel bill',
      description: 'A recent bill is the fastest way to improve accuracy. Drag and drop a PDF or photo — no manual typing needed.',
      path: '/document-upload',
      effortLabel: '~3 min',
      impactLabel: 'More accurate footprint',
      ctaLabel: 'Upload a bill',
    };
  }

  if (!input.hasAssessment) {
    return {
      title: 'See your carbon footprint',
      description: 'Walk through a short assessment to find your biggest emission sources and get practical reduction ideas.',
      path: '/carbon-footprint?section=start-assessment',
      effortLabel: '~15 min',
      impactLabel: 'Know your baseline',
      ctaLabel: 'Start assessment',
    };
  }

  if (!input.hasReportGoal) {
    return {
      title: 'Pick one report goal',
      description:
        'Choose buyer, bank, or export — we open the matching disclosure pack with readiness status and downloads.',
      path: '/reporting',
      effortLabel: '~5 min',
      impactLabel: 'Report-ready pack',
      ctaLabel: 'Choose report goal',
    };
  }

  if (input.carbonScore > 0 && input.carbonScore < 60) {
    return {
      title: 'Close gaps for your report',
      description:
        'Follow the 3-step readiness checklist, then download your disclosure pack when scores look healthy.',
      path: '/reporting',
      effortLabel: '~5 min',
      impactLabel: 'Disclosure readiness',
      ctaLabel: 'Open my report',
    };
  }

  if (input.topRecommendationTitle) {
    return {
      title: 'Act on a reduction idea',
      description: `Next: ${input.topRecommendationTitle}${
        input.topRecommendationKg != null && input.topRecommendationKg > 0
          ? ` (about ${Math.round(input.topRecommendationKg).toLocaleString('en-IN')} kg CO₂e).`
          : '.'
      } Then check green finance matches.`,
      path: '/carbon-footprint?section=recommendations',
      effortLabel: '~10 min',
      impactLabel: 'Reduce → finance',
      ctaLabel: 'Open reduction ideas',
    };
  }

  return {
    title: 'Reduce, then unlock finance',
    description:
      'Your report pack is ready. Pick a reduction idea, then open Finance for ADEETIE, green loans, or GIFT schemes.',
    path: '/carbon-footprint?section=recommendations',
    effortLabel: '~10 min',
    impactLabel: 'Reduce → finance',
    ctaLabel: 'See reduction ideas',
  };
}

export function deriveFinanceNextBestAction(input: {
  hasAssessment: boolean;
  eligibleCount: number;
  inProgressCount: number;
}): NextBestAction | null {
  if (!input.hasAssessment) {
    return {
      title: 'Run a carbon assessment to unlock finance',
      description: 'Green loans and government schemes use your emissions track record to determine eligibility.',
      path: '/carbon-footprint?section=start-assessment',
      effortLabel: '~15 min',
      impactLabel: 'Finance eligibility',
      ctaLabel: 'Start assessment',
    };
  }

  if (input.eligibleCount > 0) {
    return {
      title: `Explore ${input.eligibleCount} finance option${input.eligibleCount === 1 ? '' : 's'}`,
      description: 'Your reduction actions qualify you for ADEETIE, green loans, GIFT schemes, or rewards.',
      path: '/finance',
      impactLabel: `${input.eligibleCount} eligible`,
      effortLabel: '~5 min',
      ctaLabel: 'Open finance hub',
    };
  }

  if (input.inProgressCount > 0) {
    return {
      title: 'Complete finance readiness steps',
      description: 'You are close — finish remaining criteria to unlock green loans and incentive schemes.',
      path: '/finance',
      impactLabel: `${input.inProgressCount} in progress`,
      ctaLabel: 'View next steps',
    };
  }

  return {
    title: 'Build your finance eligibility profile',
    description: 'Upload evidence, implement recommendations, and set reduction targets to qualify for green finance.',
    path: '/finance',
    effortLabel: '~10 min',
    ctaLabel: 'Check finance options',
  };
}

/** Prefer AI goal-advisor action when MSME advisory orchestration has run. */
export function deriveNextBestActionFromAdvisory(
  fallback: NextBestAction,
  advisoryAction?: {
    title?: string;
    description?: string;
    path?: string;
    priority?: string;
  } | null
): NextBestAction {
  if (!advisoryAction?.path) {
    return fallback;
  }
  return {
    title: advisoryAction.title || fallback.title,
    description: advisoryAction.description || fallback.description,
    path: advisoryAction.path,
    ctaLabel: 'Take action',
    impactLabel: advisoryAction.priority === 'high' ? 'AI priority' : fallback.impactLabel,
    effortLabel: fallback.effortLabel,
  };
}

