export const getGlossaryLocaleEntry = (
  termId: string,
  locale: ReadinessLocale
): GlossaryLocaleEntry | undefined => {
  if (locale === 'en') {
    return undefined;
  }
  return GLOSSARY_LOCALE_ENTRIES[locale]?.[termId];
};
